import {ONLINE_PROTOCOL,roomCode,validRoomCode,safeOnlineInput,applyOnlineState} from './online-protocol.js';
import {createFootballSimulation} from './football-simulation.js';
export async function requestOnlineSeat(code,options={},fetcher=globalThis.fetch){const cleaned=roomCode(code);if(code&&!validRoomCode(cleaned))throw Error('请输入 8 位房间码');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetcher('/api/online/rooms'+(code?'/'+cleaned+'/join':''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(options),signal:controller.signal});}catch{throw Error('连接失败或超时，请检查网络后重试');}finally{clearTimeout(timer);}let data;try{data=await response.json();}catch{throw Error('联机服务暂未就绪，请稍后重试');}if(!response.ok)throw Error(data.error||'房间连接失败');return data;}
export function createOnlineSession(seat,{origin=globalThis.location?.origin,WebSocketClass=globalThis.WebSocket}={}){
 let socket=null,stopped=false,retry=null,heartbeat=null,attempt=0,firstResolve,firstReject,firstTimer,disconnectSince=0,desiredReady=false;const listeners=new Set();
 const session={...seat,connection:'connecting',error:'',room:null,packet:null,latency:0,setReady(value){desiredReady=!!value;session.send({type:'ready',ready:desiredReady});},subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},send(message){if(socket?.readyState!==1)return false;socket.send(JSON.stringify(message));return true;},sendInput(input){return session.send({type:'input',...safeOnlineInput(input)});},connect(){const promise=new Promise((resolve,reject)=>{firstResolve=resolve;firstReject=reject;});firstTimer=setTimeout(()=>{firstReject?.(Error('实时连接超时，请检查网络后重试'));session.close();},12000);open();return promise;},close(){stopped=true;clearTimeout(firstTimer);clearTimeout(retry);clearInterval(heartbeat);try{socket?.close(1000,'离开页面');}catch{}session.connection='closed';firstReject?.(Error(session.error||'连接已关闭'));firstResolve=firstReject=null;emit();},leave(){session.send({type:'leave'});session.close();}};
 function emit(){for(const fn of listeners)fn(session);}
 function open(){if(stopped)return;session.connection=attempt?'reconnecting':'connecting';emit();const url=new URL('/api/online/rooms/'+seat.code+'/socket',origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';socket=new WebSocketClass(url.href,['arena-v1','seat.'+seat.token,...(desiredReady?['ready-v1']:[])]);const current=socket;
  socket.onmessage=event=>{if(current!==socket)return;let p;try{p=JSON.parse(event.data);}catch{return;}
   if(p.type==='welcome'){if(p.protocol!==ONLINE_PROTOCOL){session.error='联机版本已更新，请刷新网页';session.close();return;}clearTimeout(firstTimer);attempt=0;disconnectSince=0;session.connection='connected';session.error='';session.room=p.room;firstResolve?.(session);firstResolve=firstReject=null;clearInterval(heartbeat);heartbeat=setInterval(()=>session.send({type:'ping',at:Date.now()}),4000);session.send({type:'ping',at:Date.now()});session.send({type:'ready',ready:desiredReady});}
   if(p.type==='state'){session.room=p.room;session.packet=p.state;if(p.room.ended)session.error=p.room.reason||'房间已结束';}
   if(p.type==='pong'&&Number.isFinite(p.at))session.latency=Math.max(0,Math.round(Date.now()-p.at));emit();
  };
  socket.onerror=()=>{};
  socket.onclose=event=>{if(current!==socket||stopped)return;clearInterval(heartbeat);if([4001,4004,1008].includes(event.code)||session.room?.ended){session.error=event.reason||session.error||'房间已结束';session.close();return;}session.connection='reconnecting';session.error='连接中断，正在重连';emit();if(!disconnectSince)disconnectSince=Date.now();if(Date.now()-disconnectSince>55000){session.error='未能重新连接，请退出后重新创建房间';session.close();return;}retry=setTimeout(open,Math.min(5000,500*2**attempt++));};
 }
 return session;
}
export function createOnlineSimulation(session,settings={}){
 const simulation=createFootballSimulation({...settings,opponent:session.opponent,humanTeams:['home','away']}),state=simulation.state,team=session.team;state.controlledId=state.controlledIds[team];state.localTeam=team;state.paused=true;state.online=true;let blend=null,sendClock=0,lastInput='',closed=false,lastPacket=null;
 function receive(){const p=session.packet;if(p&&p!==lastPacket){lastPacket=p;const positions=state.players.map(p=>({x:p.x,z:p.z,yaw:p.yaw})),ball={...state.ball},oldPhase=state.phase;if(applyOnlineState(state,p,team)){blend=oldPhase===state.phase&&state.phase==='playing'&&!state.paused?{age:0,positions,ball,targets:state.players.map(p=>({x:p.x,z:p.z,yaw:p.yaw})),targetBall:{...state.ball}}:null;}}if(session.connection!=='connected'||!session.room?.started||session.room?.ended)state.paused=true;state.onlineStatus=session.connection;}
 const unsubscribe=session.subscribe(receive);receive();
 return{state,network:session,ready(){session.setReady(true);},dispose({keepSession=false}={}){if(closed)return;closed=true;unsubscribe();if(!keepSession)session.leave();},update(dt,input={}){if(closed)return state;sendClock+=dt;const safe=safeOnlineInput(state.paused?{}:{...input,power:state.chargePower}),key=JSON.stringify(safe);if(sendClock>=.05&&(key!==lastInput||sendClock>=.2)){session.sendInput(safe);sendClock=0;lastInput=key;}
  if(blend&&!state.paused){blend.age+=Math.min(dt,.1);const t=Math.min(1,blend.age/.065);for(let i=0;i<22;i++){const p=state.players[i],a=blend.positions[i],b=blend.targets[i];p.x=a.x+(b.x-a.x)*t;p.z=a.z+(b.z-a.z)*t;p.yaw=a.yaw+Math.atan2(Math.sin(b.yaw-a.yaw),Math.cos(b.yaw-a.yaw))*t;}if(Math.hypot(blend.ball.x-blend.targetBall.x,blend.ball.z-blend.targetBall.z)<6)for(const k of ['x','y','z'])state.ball[k]=blend.ball[k]+(blend.targetBall[k]-blend.ball[k])*t;if(t>=1)blend=null;}return state;},action(type,options={}){if(state.paused||state.phase!=='playing')return false;return session.send({type:'action',action:type,direction:safeOnlineInput(options.direction),power:options.power});},setPaused(value){session.sendInput({});session.send({type:'pause',paused:!!value});if(value)state.paused=true;},setControlMode(mode){state.controlMode=mode;session.send({type:'mode',mode});return mode;},setShotKind(kind){state.shotKind=kind;session.send({type:'shot-kind',kind});return kind;}};
}
